import type { CanvasDocumentState } from '#workbench/canvas-bridge'
import { workspaceFetch } from '@/app/document/workspace-fetch'
import { fromUint8Array } from 'js-base64'
import * as v from 'valibot'
import { computed, ref, watch } from 'vue'
import type { Editor } from '@open-pencil/core/editor'
import { exportFigFile } from '@open-pencil/core/io/formats/fig'
import { SceneGraph } from '@open-pencil/scene-graph'
import { setPageBackgrounds } from '@open-pencil/core/figma-api'
import { PAGE_DEFAULT_BACKGROUNDS } from '@open-pencil/core/constants'
import { createDocumentChanges } from '@/app/document/io/changes'
import { createLocalIdentity, localNodeId } from '@/app/document/local-identity'
import { readFigDocument } from '@/app/document/io/fig'
import { applyImportedDocument } from '@/app/document/io/imported-document'
import { attachOutputOrigins, fileEntrySchema, referencedFileMounts, selectedFileLink, reconcileFileNodes } from '@/app/document/local-file-nodes'
import { ensureGraphFonts } from '@/app/editor/fonts'
import { createLocalReplacement } from '@/app/document/local-replacement'
import { createLocalRelink } from '@/app/document/local-relink'
import { createLocalMountRelink } from '@/app/document/local-mount-relink'
import { createLocalOutput } from '@/app/document/local-output'
import { createLocalPackages } from '@/app/document/local-packages'
import { createLocalFilter } from '@/app/document/local-filter-session'

type LocalEditor = Editor & {
  state: Editor['state'] & { documentName: string; autosaveEnabled: boolean }
  hasUnsavedChanges(): boolean
  markDocumentSaved(): void
  protectSavedRecovery(): Promise<void>
  saveFigFile(): Promise<boolean>
  openFigFile(file: File): Promise<void>
  setDocumentSource(fileName: string, sourceFormat: string): void
  renderExportImage(ids: string[], scale: number, format: 'PNG'): Promise<Uint8Array | null>
}

const sessions = new WeakMap<LocalEditor, ReturnType<typeof createLocalWorkspace>>()
export function getLocalWorkspace(store: LocalEditor) {
  const session = sessions.get(store)
  if (!session) throw new Error('Local workspace session was not installed')
  return session
}
export function installLocalWorkspace(store: LocalEditor) {
  const session = createLocalWorkspace(store)
  sessions.set(store, session)
  store.saveFigFile = session.save
  store.hasUnsavedChanges = session.hasUnsavedChanges
  const dispose = store.dispose.bind(store)
  store.dispose = () => { session.dispose(); sessions.delete(store); dispose() }
}

const savedSchema = v.object({ canvasId: v.string(), revision: v.number() })
const finite = v.pipe(v.number(), v.finite())
const viewSchema = v.looseObject({ pageId: v.optional(v.string()), panX: finite, panY: finite,
  zoom: v.pipe(finite, v.minValue(0.02), v.maxValue(256)) })
const metadataSchema = v.looseObject({ formatVersion: v.literal(1), name: v.string(), view: v.optional(viewSchema),
  pages: v.optional(v.array(v.looseObject({ id: v.string(), name: v.string() }))) })
// Listing needs only the envelope; validate the supported payload before opening it.
const documentSchema = v.object({ canvasId: v.string(), revision: v.number(),
  metadata: v.looseObject({ formatVersion: finite, name: v.string() }) })
type StoredDocument = v.InferOutput<typeof documentSchema>
const mountSchema = v.object({ id: v.string(), canvasId: v.string(), path: v.string(),
  availability: v.picklist(['available', 'offline', 'replaced', 'unavailable']) })
type StoredMount = v.InferOutput<typeof mountSchema>
const scanSchema = v.object({ mount: mountSchema, entries: v.array(fileEntrySchema), scanStatus: v.string() })

class WorkspaceRequestError extends Error {
  constructor(readonly status: number, message: string) { super(message); this.name = 'WorkspaceRequestError' }
}
async function request(path: string, init?: RequestInit) {
  const response = await workspaceFetch(`/os-workspace${path}`, {
    ...init, headers: { 'X-OS-Workspace': '1', 'Content-Type': 'application/json' },
    signal: AbortSignal.timeout(30000)
  })
  if (!response.ok) throw new WorkspaceRequestError(response.status, response.status === 409
    ? '画布已有更新，请保留当前内容后重新打开。'
    : '本机保存服务不可用，内容仍保留在画布中。')
  return response
}

function createLocalWorkspace(store: LocalEditor) {
  const contentDirty = store.hasUnsavedChanges.bind(store)
  store.state.autosaveEnabled = true
  const busy = ref(false)
  const bridgePaused = ref(false)
  const failureStatus = ref(0)
  let requestOpen: ((canvasId: string) => void) | undefined
  let bridgeOpening = false
  let bridgeBeforeCommit: (() => void) | undefined
  const error = ref('')
  const status = ref('尚未保存到本机')
  const documents = ref<StoredDocument[]>([])
  const history = ref<StoredDocument[]>([])
  const mounts = ref<StoredMount[]>([])
  const mountBusy = ref(false)
  const currentMountId = ref('')
  const scanBusy = ref(false)
  const scanStatus = ref('')
  const stagedRestore = ref(false)
  let canvasId: string = crypto.randomUUID()
  let revision = 0
  let retainedMetadata: v.InferOutput<typeof metadataSchema> | undefined
  let generation = 0
  let opening = false
  let disposed = false
  let timer: ReturnType<typeof setTimeout> | undefined
  let scanTimer: ReturnType<typeof setTimeout> | undefined
  const changes = createDocumentChanges(store)
  const identity = createLocalIdentity(store)
  const filter = createLocalFilter(store)
  const output = createLocalOutput(store, () => ({ canvasId, mountId: currentMountId.value,
    revision, version: changes.capture() }), save, scanFiles, schedule)
  const packages = createLocalPackages(() => ({ canvasId, revision, generation }), save, refresh,
    () => busy.value || scanBusy.value || output.busy.value || mountBusy.value)
  const viewVersion = ref(0)
  const savedViewVersion = ref(0)
  const viewDirty = computed(() => viewVersion.value !== savedViewVersion.value)
  // Keep exact input across an uncertain response, so retry cannot duplicate a commit.
  let pending: { body: string; version: number; viewVersion: number } | undefined

  function schedule() {
    clearTimeout(timer)
    if (disposed || opening || bridgePaused.value || !store.state.autosaveEnabled || error.value ||
        (revision === 0 && !contentDirty()) || (!contentDirty() && !viewDirty.value && !stagedRestore.value)) return
    timer = setTimeout(() => { if (!busy.value && !output.busy.value) void save() }, 1000)
  }
  const stopDirtyWatch = watch(() => [contentDirty(), store.state.autosaveEnabled, viewVersion.value], schedule)
  const stopViewWatch = store.onEditorEvent('viewport:changed', () => { if (!opening) viewVersion.value++ })
  const stopPageWatch = watch(() => store.state.currentPageId, () => { if (!opening) viewVersion.value++ })
  const stopGraphWatch = store.onEditorEvent('graph:replaced', () => {
    if (opening) return
    generation++; canvasId = crypto.randomUUID(); revision = 0; pending = undefined
    retainedMetadata = undefined
    currentMountId.value = ''; scanStatus.value = ''
    history.value = []; stagedRestore.value = false
    viewVersion.value = 0; savedViewVersion.value = 0
    status.value = '尚未保存到本机'; error.value = ''; clearTimeout(timer)
  })

  async function refresh() {
    try {
      const response = await request('/canvases')
      documents.value = v.parse(v.pipe(v.string(), v.parseJson(), v.array(documentSchema)), await response.text())
    } catch (cause) { error.value = cause instanceof Error ? cause.message : '无法读取本机画布' }
  }

  async function refreshMounts() {
    try {
      const response = await request('/mounts')
      mounts.value = v.parse(v.pipe(v.string(), v.parseJson(), v.array(mountSchema)), await response.text())
    } catch (cause) { error.value = cause instanceof Error ? cause.message : '无法读取目录' }
  }

  async function scanFiles() { await scanDirectory(false) }

  function canScanDirectory(automatic: boolean) {
    return Boolean(currentMountId.value) && !bridgePaused.value && !scanBusy.value && !busy.value && !opening &&
      !stagedRestore.value && !(automatic && output.busy.value)
  }

  async function scanDirectory(automatic: boolean) {
    if (!canScanDirectory(automatic)) return
    const target = currentMountId.value, graph = store.graph
    const isCurrentScan = () => !disposed && store.graph === graph && currentMountId.value === target
    scanBusy.value = true
    if (!automatic) scanStatus.value = '正在扫描目录'
    try {
      const references = referencedFileMounts(store, target)
      const results = await Promise.all([...references.keys()].map(async id => {
        const response = await request(`/mounts/${id}/${automatic ? 'poll' : 'scan'}`, { method: 'POST' })
        return v.parse(v.pipe(v.string(), v.parseJson(), scanSchema), await response.text())
      }))
      if (!isCurrentScan()) return
      let knownFileAssets = readKnownFileAssets(retainedMetadata?.knownFileAssets)
      const textIds: string[] = []
      for (const result of results) {
        const entries = result.mount.id === target ? result.entries
          : result.entries.filter(entry => references.get(result.mount.id)?.has(entry.id))
        attachOutputOrigins(store, entries, canvasId)
        const reconciled = reconcileFileNodes(store, entries, knownFileAssets, result.mount.availability)
        knownFileAssets = reconciled.knownFileAssets; textIds.push(...reconciled.textIds)
      }
      if (retainedMetadata) retainedMetadata = { ...retainedMetadata, knownFileAssets }
      if (textIds.length) {
        await ensureGraphFonts(graph, textIds, store.renderer)
        if (!isCurrentScan()) return
        for (const id of textIds) store.runLayoutForNode(id)
        store.requestRender()
      }
      scanStatus.value = results.every(result => result.scanStatus === 'complete') ? '目录与关联文件已更新'
        : '目录暂不可完整读取，已保留原有内容'
      schedule()
    } catch (cause) {
      if (!isCurrentScan()) return
      scanStatus.value = '目录刷新失败，原有内容保留'
      if (!automatic) error.value = cause instanceof Error ? cause.message : '目录刷新失败'
    } finally { scanBusy.value = false }
  }

  function scheduleDirectoryScan() {
    clearTimeout(scanTimer)
    if (disposed || !currentMountId.value) return
    scanTimer = setTimeout(() => {
      void scanDirectory(true).finally(scheduleDirectoryScan)
    }, 1500)
  }
  const stopMountWatch = watch(currentMountId, scheduleDirectoryScan)
  const replacement = createLocalReplacement(store, () => currentMountId.value, scanFiles)
  const relink = createLocalRelink(store, scanFiles)
  const mountRelink = createLocalMountRelink(store, () => currentMountId.value, async () => {
    await refreshMounts(); await scanFiles()
  })

  async function openMount(mount: StoredMount) {
    if (busy.value || mountBusy.value) return
    if (pending || contentDirty() || viewDirty.value || stagedRestore.value) {
      error.value = '当前画布有未保存内容，请先保存再打开目录。'; return
    }
    mountBusy.value = true; error.value = ''
    const previousGraph = store.graph
    try {
      const response = await request('/canvases')
      let entries = v.parse(v.pipe(v.string(), v.parseJson(), v.array(documentSchema)), await response.text())
      let document = entries.find(entry => entry.canvasId === mount.canvasId)
      if (!document) {
        if (mount.availability !== 'available') throw new Error('目录当前不可用，尚未创建对应画布。')
        const graph = new SceneGraph()
        for (const page of graph.getPages()) setPageBackgrounds(graph, page, [{ type: 'SOLID',
          color: { ...PAGE_DEFAULT_BACKGROUNDS[store.state.theme ?? 'dark'] }, opacity: 1, visible: true, blendMode: 'NORMAL' }])
        const pages = graph.getPages().map(page => ({ id: crypto.randomUUID(), name: page.name }))
        const scene = await exportFigFile(graph)
        const metadata = { formatVersion: 1, name: mountDisplayName(mount.path),
          mountId: mount.id, pages, view: { pageId: pages[0]?.id, panX: 0, panY: 0, zoom: 1 } }
        const created = await workspaceFetch(`/os-workspace/canvases/${mount.canvasId}`, { method: 'POST',
          headers: { 'X-OS-Workspace': '1', 'Content-Type': 'application/json' }, signal: AbortSignal.timeout(30000),
          body: JSON.stringify({ operationId: crypto.randomUUID(), expectedRevision: 0,
            sceneBase64: fromUint8Array(scene), metadata }) })
        if (!created.ok && created.status !== 409) throw new Error('目录画布尚未保存，请重试加入目录。')
        // Another window may have provisioned the reserved ID. Load its confirmed head.
        const current = await request('/canvases')
        entries = v.parse(v.pipe(v.string(), v.parseJson(), v.array(documentSchema)), await current.text())
        document = entries.find(entry => entry.canvasId === mount.canvasId)
      }
      if (!document) throw new Error('目录画布尚未完成创建，请重试。')
      if (disposed) return
      if (store.graph !== previousGraph) throw new Error('已切换画布，目录已登记，请重新打开。')
      if (await open(document)) await scanFiles()
      await refresh()
    } catch (cause) { error.value = cause instanceof Error ? cause.message : '无法打开目录画布' }
    finally { mountBusy.value = false }
  }

  async function addMount(path: string) {
    if (busy.value || mountBusy.value) return
    mountBusy.value = true; error.value = ''
    let mount: StoredMount | undefined
    try {
      const response = await request('/mounts', { method: 'POST', body: JSON.stringify({ path: path.trim() }) })
      mount = v.parse(v.pipe(v.string(), v.parseJson(), mountSchema), await response.text())
      await refreshMounts()
    } catch (cause) { error.value = cause instanceof Error ? cause.message : '无法加入目录' }
    finally { mountBusy.value = false }
    if (mount && !disposed) await openMount(mount)
  }

  async function openSelectedFolder() {
    if (busy.value || mountBusy.value) return
    const link = selectedFileLink(store)
    if (link?.kind !== 'directory' || link.mountId !== currentMountId.value) {
      error.value = '请先在画布中选中一个本地文件夹节点。'; return
    }
    const previousGraph = store.graph
    const isCurrent = () => !disposed && store.graph === previousGraph
    if (contentDirty() || viewDirty.value || pending || stagedRestore.value) {
      if (!await save() || !isCurrent()) return
    }
    mountBusy.value = true; error.value = ''
    let mount: StoredMount | undefined
    try {
      const response = await request(`/mounts/${link.mountId}/files/${link.id}/open`, { method: 'POST' })
      mount = v.parse(v.pipe(v.string(), v.parseJson(), mountSchema), await response.text())
      await refreshMounts()
    } catch (cause) { error.value = cause instanceof Error ? cause.message : '无法打开文件夹' }
    finally { mountBusy.value = false }
    if (mount && isCurrent()) await openMount(mount)
  }

  // Read lifecycle state after each await; another callback can dispose this session.
  function isCurrentGeneration(expected: number) {
    return expected === generation && !disposed
  }

  async function save() {
    if (busy.value || disposed) return false
    clearTimeout(timer)
    const currentGeneration = generation
    const targetId = canvasId
    busy.value = true; error.value = ''; failureStatus.value = 0; status.value = '正在保存'
    try {
      if (!pending) {
        // Finish coalesced arrow edits before capturing their history and geometry.
        store.flushNudge()
        // Group fitting can queue derived connection updates in the same edit.
        await Promise.resolve()
        if (!isCurrentGeneration(currentGeneration)) return false
        identity.ensureAll()
        const version = changes.capture()
        const capturedViewVersion = viewVersion.value
        const pages = identity.pageIdentities().map(page => ({
          ...retainedMetadata?.pages?.find(saved => saved.id === page.id), ...page
        }))
        const view = { ...retainedMetadata?.view, pageId: localNodeId(store.graph.getNode(store.state.currentPageId)),
          panX: store.state.panX, panY: store.state.panY, zoom: store.state.zoom }
        const outputSourceNodeIds = [...store.graph.nodes.values()].map(localNodeId).filter(id => id !== undefined)
        const scene = await exportFigFile(store.graph, undefined, undefined, store.state.currentPageId)
        if (!isCurrentGeneration(currentGeneration)) return false
        pending = { version, viewVersion: capturedViewVersion, body: JSON.stringify({ operationId: crypto.randomUUID(),
          expectedRevision: revision, sceneBase64: fromUint8Array(scene),
          metadata: { ...retainedMetadata, formatVersion: 1, name: store.state.documentName || '未命名画布', view, pages, outputSourceNodeIds } }) }
      }
      const snapshot = pending
      const response = await request(`/canvases/${targetId}`, { method: 'POST', body: snapshot.body })
      const saved = v.parse(v.pipe(v.string(), v.parseJson(), savedSchema), await response.text())
      if (saved.canvasId !== targetId) throw new Error('保存返回的画布身份不匹配')
      if (!isCurrentGeneration(currentGeneration)) return false
      revision = saved.revision
      stagedRestore.value = false
      const currentVersion = changes.capture()
      changes.markSaved(snapshot.version)
      savedViewVersion.value = snapshot.viewVersion
      if (currentVersion === snapshot.version) {
        store.markDocumentSaved()
        await store.protectSavedRecovery()
        if (!isCurrentGeneration(currentGeneration)) return false
        status.value = '已保存到本机'
      } else status.value = '旧快照已保存，仍有新改动'
      pending = undefined
      await refresh()
      return !contentDirty() && !viewDirty.value
    } catch (cause) {
      if (!isCurrentGeneration(currentGeneration)) return false
      failureStatus.value = cause instanceof WorkspaceRequestError ? cause.status : 0
      status.value = '保存失败，可重试'
      error.value = cause instanceof Error ? cause.message : '保存失败'
      return false
    } finally { busy.value = false; schedule() }
  }

  async function showHistory() {
    if (busy.value) return
    const target = canvasId
    try {
      const response = await request(`/canvases/${canvasId}/revisions`)
      if (target !== canvasId || disposed) return
      history.value = v.parse(v.pipe(v.string(), v.parseJson(), v.array(documentSchema)), await response.text())
    } catch (cause) { error.value = cause instanceof Error ? cause.message : '无法读取历史版本' }
  }

  async function open(document: StoredDocument, restore = false): Promise<boolean> {
    if (requestOpen && !bridgeOpening && !restore) { requestOpen(document.canvasId); return false }
    return openDocument(document, restore)
  }
  async function openDocument(document: StoredDocument, restore: boolean): Promise<boolean> {
    if (busy.value) return false
    if (document.metadata.formatVersion !== 1) {
      error.value = '不支持的作品格式，请使用兼容版本打开；原作品未修改。'
      return false
    }
    const parsed = v.safeParse(metadataSchema, document.metadata)
    if (!parsed.success) {
      error.value = '作品元数据损坏或不兼容，原作品未修改。'
      return false
    }
    const metadata = parsed.output
    if (pending || contentDirty() || viewDirty.value || stagedRestore.value) {
      error.value = '当前画布有未保存内容，请先保存再打开其他画布。'; return false
    }
    clearTimeout(timer)
    busy.value = true; error.value = ''; opening = true
    const previousGraph = store.graph
    const previousRevision = revision
    const previousVersion = changes.capture()
    const previousView = { panX: store.state.panX, panY: store.state.panY,
      zoom: store.state.zoom, pageId: store.state.currentPageId }
    try {
      const response = await request(`/canvases/${document.canvasId}/scene?revision=${document.revision}`)
      const file = new File([await response.arrayBuffer()], `${metadata.name}.fig`)
      const imported = await readFigDocument(file)
      const savedPageIndex = metadata.pages?.findIndex(page => page.id === metadata.view?.pageId) ?? -1
      const targetPage = savedPageIndex >= 0 ? imported.getPages()[savedPageIndex]?.id : undefined
      await applyImportedDocument(store, imported, undefined, () => {
        bridgeBeforeCommit?.()
        const viewChanged = store.state.panX !== previousView.panX || store.state.panY !== previousView.panY ||
          store.state.zoom !== previousView.zoom || store.state.currentPageId !== previousView.pageId
        if (viewChanged) viewVersion.value++
        if (disposed || store.graph !== previousGraph || changes.capture() !== previousVersion || viewChanged) {
          throw new Error('打开期间发生新编辑，已保留当前内容，请重试。')
        }
      }, { pageId: targetPage, prepare: staging => {
        const stagedIdentity = createLocalIdentity(staging)
        try { if (metadata.pages) stagedIdentity.restorePages(metadata.pages) }
        finally { stagedIdentity.dispose() }
      } })
      store.state.documentName = metadata.name
      store.setDocumentSource(file.name, 'fig')
      const appliedVersion = changes.capture()
      const view = metadata.view
      if (view) {
        store.setZoomAroundPoint(view.zoom, 0, 0)
        store.pan(view.panX - store.state.panX, view.panY - store.state.panY)
      }
      viewVersion.value = 0; savedViewVersion.value = 0
      canvasId = document.canvasId; revision = restore ? previousRevision : document.revision
      retainedMetadata = metadata
      currentMountId.value = typeof metadata.mountId === 'string' ? metadata.mountId : ''
      scanStatus.value = ''
      store.state.autosaveEnabled = true
      stagedRestore.value = restore
      if (changes.capture() === appliedVersion) {
        changes.markSaved()
        store.markDocumentSaved()
      }
      status.value = restore ? '历史版本已载入，正在保存为新修订' : '已保存到本机'
      void output.loadRecovery()
      return true
    } catch (cause) {
      if (store.graph !== previousGraph) {
        generation++; canvasId = crypto.randomUUID(); revision = 0; pending = undefined
        retainedMetadata = undefined
        currentMountId.value = ''; scanStatus.value = ''
        status.value = '打开未完成，尚未关联本机画布'
      }
      error.value = cause instanceof Error ? cause.message : '打开失败'
      return false
    }
    finally { busy.value = false; opening = false }
  }
  async function restoreVersion(document: StoredDocument) {
    if (document.canvasId !== canvasId) { error.value = '历史列表已过期，请重新读取。'; return }
    if (await open(document, true)) { await save(); await showHistory() }
  }
  function bridgeSnapshot(): CanvasDocumentState & { canvasId: string } {
    const dirty = contentDirty() || viewDirty.value || Boolean(pending) || stagedRestore.value
    let state: CanvasDocumentState['state'] = 'editable'
    if (revision > 0) state = 'saved'
    if (dirty) state = 'dirty'
    if (error.value) state = 'save-failed'
    if (error.value && failureStatus.value === 409) state = 'conflict'
    if (error.value && failureStatus.value === 503) state = 'offline'
    if (busy.value) state = 'saving'
    if (opening) state = 'loading'
    return { canvasId, state, revision, dirty, ...(error.value ? { error: error.value.slice(0, 1024) } : {}) }
  }
  function bridgeBusy() { return busy.value || scanBusy.value || mountBusy.value || output.busy.value || opening }
  async function saveForBridge() {
    const deadline = Date.now() + 30000
    while (bridgeBusy()) {
      if (disposed || Date.now() >= deadline) throw new Error('Canvas operations did not settle')
      await new Promise(resolve => { setTimeout(resolve, 20) })
    }
    if (disposed) throw new Error('Canvas session is closed')
    // An untouched draft stays memory-only even after a viewport gesture.
    if (revision === 0 && !contentDirty() && !pending && !stagedRestore.value) {
      savedViewVersion.value = viewVersion.value
      return bridgeSnapshot()
    }
    if (contentDirty() || viewDirty.value || pending || stagedRestore.value) {
      if (!await save()) throw new Error(error.value || 'Canvas save was not confirmed')
    } else if (error.value) {
      // A list refresh may fail after a successful commit. Retry that read rather
      // than leaving a clean document permanently failed or adding a revision.
      error.value = ''; failureStatus.value = 0
      await refresh()
      if (error.value) throw new Error(error.value)
    }
    return bridgeSnapshot()
  }
  async function openFromBridge(targetId: string, beforeCommit?: () => void) {
    const response = await request(`/canvases/${targetId}`)
    const document = v.parse(v.pipe(v.string(), v.parseJson(), documentSchema), await response.text())
    if (document.canvasId !== targetId) throw new Error('Canvas identity mismatch')
    bridgeOpening = true; bridgeBeforeCommit = beforeCommit
    try { if (!await open(document)) throw new Error(error.value || 'Canvas did not open') }
    finally { bridgeOpening = false; bridgeBeforeCommit = undefined }
    return bridgeSnapshot()
  }
  function pauseForBridge(paused: boolean) {
    bridgePaused.value = paused
    if (paused) clearTimeout(timer)
    else schedule()
  }
  const visibleStatus = computed(() => status.value === '已保存到本机' && (contentDirty() || viewDirty.value)
    ? '有未保存改动' : status.value)
  function dispose() {
    packages.dispose()
    filter.dispose()
    replacement.dispose()
    relink.dispose()
    mountRelink.dispose()
    output.dispose()
    clearTimeout(scanTimer); stopMountWatch()
    disposed = true; clearTimeout(timer); stopDirtyWatch(); stopGraphWatch(); stopViewWatch(); stopPageWatch(); changes.dispose(); identity.dispose()
  }
  return { bridgeSnapshot, saveForBridge, openFromBridge, pauseForBridge,
    setOpenRequest: (handler?: (canvasId: string) => void) => { requestOpen = handler },
    packages, filter, output, mountRelink, relink, replacement, busy, mountBusy, mounts, refreshMounts, addMount, openMount, openSelectedFolder, currentMountId, scanBusy, scanStatus, scanFiles, error, status: visibleStatus, documents, history, save, refresh, open, showHistory, restoreVersion, dispose,
    hasUnsavedChanges: () => contentDirty() || viewDirty.value || Boolean(pending) || stagedRestore.value }
}

function mountDisplayName(path: string) {
  return path.split(/[\\/]/).findLast(part => part.length > 0) ?? '文件夹画布'
}

function readKnownFileAssets(value: unknown) {
  const parsed = v.safeParse(v.array(v.string()), value)
  return parsed.success ? parsed.output : []
}

